package vn.svframe.svframelib.script.condition.misc;import vn.svframe.svframelib.script.condition.RawCondition;import vn.svframe.svframelib.util.configobject.ConfigObject;public class CooldownCondition extends RawCondition{public CooldownCondition(ConfigObject c){super("cooldown"+render(c));}private static String render(ConfigObject c){if(c==null||c.getKeys().isEmpty())return "";StringBuilder b=new StringBuilder("{");boolean first=true;for(String k:c.getKeys()){if(!first)b.append(';');first=false;b.append(k).append('=').append(c.getString(k,""));}return b.append('}').toString();}}